import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BWuWLRhz.js";const h=JSON.parse('{"title":"バージョン情報","description":"","frontmatter":{},"headers":[],"relativePath":"ja-JP/user-guide/settings/about.md","filePath":"ja-JP/user-guide/settings/about.md","lastUpdated":1786082398000}'),s={name:"ja-JP/user-guide/settings/about.md"};function n(i,e,l,d,c,u){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="バージョン情報" tabindex="-1">バージョン情報 <a class="header-anchor" href="#バージョン情報" aria-label="Permalink to &quot;バージョン情報&quot;">​</a></h1><p>App、Core、Service、CLI 各コンポーネントのバージョン番号(サービスが現在正常かどうかを反映して色分けされます)、Lertaro の簡単な説明、プロジェクトのホームページとオンラインユーザーガイドへのリンクを表示します。</p><h2 id="データ-フォルダー" tabindex="-1">データ フォルダー <a class="header-anchor" href="#データ-フォルダー" aria-label="Permalink to &quot;データ フォルダー&quot;">​</a></h2><p>その下にはさらに 2 つのリンクがあり、Lertaro が自身の設定を読み書きしているフォルダーを開きます。それぞれ実際のパスがクリック可能なリンクテキストとして表示され、フォルダーがまだ存在しない場合は先に作成されます。</p><ul><li><strong>ユーザー データ フォルダー</strong> — <code>user-settings.json</code> を保持するユーザーごとのフォルダーです。設定が保存されるたびに、新しいファイルが書き込まれる前に以前のファイルが <code>user-settings.json.bak.1</code> にローテーションされ(古いバックアップは <code>.bak.5</code> まで繰り下げられます)、誤った編集や保存中のクラッシュがあっても、常に直近のコピーから復元できるようになっています。履歴、証明書、ユーザー固有のキャッシュもここに保存されます。</li><li><strong>マシン データ フォルダー</strong> — バックグラウンドサービスが使用するマシン全体のフォルダーです(<code>machine-settings.json</code>、ローカル ドライブのインデックス キャッシュ、サービス側のログなど)。</li></ul><p>インストーラー版では <code>%LocalAppData%\\Lertaro</code> と <code>%ProgramData%\\Lertaro</code> を使用します。ポータブル版ではアプリケーションの横にある <code>Data\\Users\\&lt;SID hash&gt;</code> と <code>Data\\Machine</code> を使用します。ポータブル版の <code>Data</code> フォルダーがまだ作成されていない場合は、互換性のため既存のインストーラー版データを再利用します。優先順位は<a href="./../getting-started.html#ポータブル-データ">ポータブル データ</a>を参照してください。</p><h2 id="アップデートの確認" tabindex="-1">アップデートの確認 <a class="header-anchor" href="#アップデートの確認" aria-label="Permalink to &quot;アップデートの確認&quot;">​</a></h2><ul><li><strong>アップデートを確認</strong> ボタン — 新しいリリースがないか問い合わせます。ボタン自体のラベルが進行状況を反映します(「確認中...」の後、「最新です」または見つかった新しいバージョン番号のいずれかになります)。</li><li>非管理者アカウントがその場でアップデートをインストールするためにバックグラウンドサービスを停止できない場合、警告バナーがその旨を説明し、代わりに手動ダウンロードページへ誘導します。</li><li>新しいバージョンが見つかると: <ul><li><strong>サイレント自動更新</strong> — バックグラウンドでダウンロードとインストールを行い、進行状況バーを表示した後、Lertaro を自動的に再起動します。</li><li><strong>ダウンロードページへ移動</strong> — 手動インストール用に、ブラウザで GitHub のリリースページを開きます。</li></ul></li></ul><p>これは <a href="./general.html#システム">一般 → システム</a> にある <strong>アップデートの自動確認</strong> / <strong>サイレント自動更新</strong> チェックボックスと連動しています。それらは起動時にこの確認を自動的に行うかどうかを制御するもので、このページではいつでも手動でトリガーできます。</p>',9)])])}const p=t(s,[["render",n]]);export{h as __pageData,p as default};
